"""Stage 2B-3 人工逐方向整理的事实；仅作为构建输入，不高于原著。"""
rows=[]
def R(a,b,kind,end,stages,dims='',boundary='',temps='',family=None,asym=False,anchors=None):
    ds={}
    for x in dims.split('||'):
        if x: k,v=x.split('=',1);ds[k]=v
    rows.append(dict(id=f'REL{len(rows)+1:03}',source=f'CH{a:03}',target=f'CH{b:03}',categories=kind.split('／'),end=end,stages=[dict(event=f'EV{n:04}',claim=t) for n,t in stages],dimensions=ds,boundary=boundary,temp_ids=[f'REL_TEMP_{int(t):03}' for t in temps.split(',') if t],family=family,asymmetric=asym,anchors=anchors or []))

