R(1,2,'家庭／师生／责任','父女沟通已有改善；以翠雀继续教导和保护，小璐仍不知道两身份同人。',[(184,'A：女儿出生，成为父亲。'),(1,'A：父女已疏离，试图道歉未完成坦白。'),(3,'A：以翠雀救白玫；读者已知的血缘不对她公开。'),(12,'A：道歉并承诺以后解释，答应家长会。'),(15,'A：以导师指导训练与学业。'),(23,'A：承认不能替孩子理解一切，不要求替母复仇。'),(60,'A：危险后接受女儿拉手与拥抱；复仇和父职冲突限此时期。'),(92,'A：承认父女旧隔阂，尝试支持其独立需求。'),(93,'A：遭鸢威胁后恳求女儿这次留下。'),(101,'A：确认翠雀与她有独立的情感联系，接受撒娇；不承诺永不分别。'),(133,'A：说明公开评级风险，把选择权交还她。'),(135,'A：不以自己的需要阻断其留国前途，约考后再谈。')], '熟悉度=A：亲自养育并日常授课||责任=A：父亲保护与导师培养分别存在||信任=A：给予成长与公开评级的决定空间；不是全面放任||情感亲近=A：亲子关怀及接受撒娇||家庭认同=A：亲生父亲，亦接受她面向翠雀的依恋','小璐眼中的父亲与导师不能因CH合一而共享秘密；U003/U008禁止玩家出现即抹消既有亲子关系。','1,8,19',{'称呼':'A：爸爸／父亲；翠雀面貌为老师、前辈及请求中的妈妈。','主观家庭认同':'A：林昀明确把小璐视为亲生女儿。','双方情感承诺':'A：父女已有亲情；EV0101另确认翠雀面向她的依恋回应，非永久不离契约。','实际共同生活':'A：家庭生活；后入小队基地、阶段性回家。','社会公开关系':'A：林昀的女儿；翠雀的父亲同一性未公开。','法律亲属关系':'F：原著确认父女家庭，未展示法定登记文书；不以文书未知否认亲生事实。','血缘关系':'A：林昀与安雅亲生女儿；C138纠正旧卡养女。'},True,[[20854,20854],[23697,23701]] )
R(2,1,'家庭／师生／依赖','对父亲改善沟通；对翠雀明确依恋并拒绝被迫远离；秘密身份仍分开。',[(184,'A：出生于林安家庭。'),(3,'A：对白玫救援者初识与认可，与对父亲的疏离并存。'),(12,'A：给父亲解释机会并邀家长会。'),(14,'A：父亲赶到后递伞。'),(19,'A：喊爸并坦白自己的魔法少女身份。'),(23,'D：将前辈关照理解为母亲遗泽，表达死亡恐惧和成长愿望。'),(33,'A：希望变强并保护父亲。'),(60,'A：虽害怕杀敌现场，仍主动抓住翠雀的手邀请回家。'),(92,'A/D：对父亲仍陌生；想认翠为母又怕添负担。'),(101,'A：明确索求面向翠雀本人的依恋回应。'),(135,'A：拒绝紫钻要求远离矢车菊。')],'熟悉度=A：熟识父亲及导师，身份联系UNKNOWN||信任=A：向父亲坦白自身身份、向翠表达成长恐惧||依赖=A：向翠雀主动索求安慰与陪伴||情感亲近=A：分别呈现父女沟通、对翠的依恋||家庭认同=A/D：认林为父亲，向翠索求妈妈身份','血缘已证不等识破父亲；早期怕杀敌不冻结成永远害怕导师。','2,6',{'称呼':'A：父亲/爸；翠雀/前辈，EV0101提出妈妈请求。','主观家庭认同':'A：林昀为父；对翠另提出家庭式归属。','双方情感承诺':'A：EV0101获得回应；不可据此补一个新的血亲或婚姻。','实际共同生活':'A：父女原有家庭与小队基地分阶段。','社会公开关系':'A：林昀女儿；翠雀面貌只按当场公开范围。','法律亲属关系':'F：未据档案展示法律文书。','血缘关系':'A：亲生父女，自己不知父亲魔法身份不改变客观血缘。'},True)
R(1,3,'师生／责任／同伴','持续指导照护，知道其家庭困境；共享林昀身份，不确立法律收养或双向恋爱。',[(5,'A：招募时许诺保护与指导，尚未听完整家庭故事。'),(15,'A：训练及学业辅导。'),(16,'A：听其家庭遭遇，承认此前关注不足，尊重不转告小璐的要求。'),(18,'A：邀家庭纪念日行程。'),(36,'A：确认同一身份，重视其专属关系请求但要求再考虑；D：将请求理解为亲情。'),(38,'A：履行出游与生日陪伴，处理旧友伤害。'),(104,'A：继续教学；温柔与身体亲昵不等承认情侣。'),(121,'A：听其自主参考选择并告知蓝杖意向。')],'责任=A：保护、教学、关注其家庭需求||信任=A：共享身份及特定隐私；不表示全历史披露||情感亲近=A：接受亲近与关怀||恋爱倾向=F：未确认双向恋爱；翠的明确亲情解读为D||家庭认同=D：理解为亲情请求；A：收养责任暂缓考虑','EV0036不是当场收养，也不是当场答应生日约会；生日出游后叙补完。','3,10',{'称呼':'A：翠雀/老师/林叔叔随场景。','主观家庭认同':'D：翠雀把请求理解为亲情；不是已完成义女手续。','双方情感承诺':'A：保护教导承诺；EV0036明确暂缓专属家庭承诺。','实际共同生活':'A：小队基地共同生活。','社会公开关系':'A：同伴家长/老师；隐蔽身份另分。','法律亲属关系':'F：未确认收养。','血缘关系':'F：无证据确立林与夏血亲。'},True)
R(3,1,'师生／依赖／亲近','珍视并主动靠近导师及林昀；知道二者同人，但性别起源仍误解；恋爱是否相互成立未知。',[(5,'A：先应打工后因黑猫线索选择招募，不是从第一刻全知老师。'),(16,'A：向翠坦陈家庭困境与自己的需求。'),(36,'A：拨电话验证并得到同一人承认；索求属于自己的一份关系。'),(39,'D：知道旧代号仍否定男性变魔法少女的可能。'),(40,'A：珍视生日陪伴和礼物。'),(109,'A：以温柔港湾策略关心翠休息；主张不是专业读心。'),(110,'D：仍以原女后男理解翠雀，纠正被打断。')],'信任=A：向其透露家庭秘密||依赖=A：主动要求专属依恋和关照||情感亲近=A：亲昵、关心与索求有证据||恋爱倾向=F：亲吻、贴近、独占式愿望不充分确认关系性质，更不确认被接受||家庭认同=D：将其视为珍视的人并索求专属归属','对方的亲情解读不替代夏本人的完整心理；特殊待遇无完整比较不泛称唯一。','9',{'称呼':'A：林叔叔、翠雀/老师依场景。','主观家庭认同':'D：希望获得属于自己的一份亲密归属。','双方情感承诺':'A：请求发生；专属家庭承诺未当场完成。','实际共同生活':'A：借住及基地生活。','社会公开关系':'A：后辈/导师关系；身份秘密限本人。','法律亲属关系':'F：未确认收养。','血缘关系':'F：无证据确立。'},True,[[24896,24907],[25700,25749]])
R(2,3,'同伴／友情','从排斥走到共同作战、感谢与日常拌嘴并存。',[(5,'A：不喜欢新同伴，不等已互信。'),(8,'A：允许借住并倾诉家庭不满。'),(31,'A：夏为自己重伤，危局共同反击。'),(40,'A：耳钉补偿并接受对方拥抱。'),(116,'A：承认夏进步、感谢一路陪伴并送镜。')],'熟悉度=A：共住共训||信任=A：家庭倾诉及作战合作||情感亲近=A：礼物和感谢；恋爱未确认','口头拌嘴不能抹掉已发生的修复；两向另档。','4')
R(1,40,'旧识／慰问／信息传递','荼蘼已牺牲；林收到死讯及其续查安雅案的信息，保留历史关系。',[(9,'A：安雅葬礼拥抱安慰荼蘼。'),(34,'A：收到荼蘼为追查樱案断后死亡的消息。')],'情感亲近=A：葬礼慰问行为||责任=A：继续追查相关线索；不等替她作全套誓约','拥抱不是恋爱，死讯不使早期葬礼已知牺牲。','5')
R(1,12,'情报合作／敌对','先有限合作，后确认蛾并战斗杀死；早期信赖不能延续为末尾盟友。',[(13,'A：以家属身份接触局长，约有限情报互通。'),(49,'A：发现局方异常，得知红被改造并追查。'),(55,'A：摩丝公开蛾身份。'),(60,'A：追问安雅案、遭突袭后杀死摩丝。')],'信任=A：早期有限情报约定；末期失效||戒备=A：揭露后转为对抗||责任=A：救改造者并保护孩子','死亡后的关系是历史结案，不让未送达的兵触三报告进入摩丝知识。','7')
R(4,10,'友情／招募联系','实际朋友；开端的夸大许诺不抹掉真实友谊。',[(24,'A：最初有戒心，逐渐愿与摩可私会聊天。D：相信治疗眼睛等许诺不等机制成立。'),(26,'A：魔法少女觉醒，合作渠道进入小队。'),(159,'A：在基地继续共同生活。')],'熟悉度=A：从私下相识到同队||信任=A：愿意倾诉并接受邀请，有最初辨别||情感亲近=A：真实友情','治疗许诺为摩可自述；不能写白天生孤僻或全无警惕。','11')
R(4,1,'师生／家庭认同／依赖','对翠有已兑现的母亲承诺，对林有获回应的爸爸称呼；仍未确认同一身份及法律收养。',[(32,'A：受救后坚持叫老师。'),(67,'D：在误会中称林为爸爸，把林翠当两个成年人。'),(71,'A：接受翠明确的妈妈承诺，失控平息。'),(78,'A：一度退称叔叔/老师；生日说明后请求继续叫爸爸并获回应、再叫妈妈。'),(101,'A：继续母亲依恋，不由小璐的撒娇权取消。'),(107,'A：庙会公开破例称妈妈，之后仍有收口；非全面解除私下约定。'),(116,'A：用母亲字样巧克力表达珍重。')],'信任=A：向其寻求安全和家庭回应||依赖=A：母亲承诺是明确的安慰来源||情感亲近=A：依偎、称呼、送礼||家庭认同=D：分别认翠为妈、林为爸；承诺行为为A','姓名合并只是客观数据库主体合并，不让白知道林翠同人，不制造两个自然人的婚姻。','12,23',{'称呼':'A：老师→妈妈；爸爸→叔叔→爸爸。','主观家庭认同':'D：把翠雀与林昀分别视为妈妈与爸爸。','双方情感承诺':'A：EV0071母亲承诺，EV0078父亲称呼回应。','实际共同生活':'A：翠与白住基地；林来访，不等两位家长同住。','社会公开关系':'A：有公开称妈例外，也有私下约定与收口。','法律亲属关系':'F：未确认法律收养；EV0092林说明尚无手续。','血缘关系':'F：没有林白血缘证据；不改写为安雅亲女。'},True)
R(1,6,'夫妻／旧队／亲情','妻已亡，林继续哀悼和追查；不把亡妻状态当当代可行动伴侣。',[(189,'A：为救安雅主动争取成为魔法少女。'),(37,'A：旧队同伴并逐渐建立私人与家庭关系。'),(183,'A：订婚后结婚，形成夫妻家庭。'),(184,'A：共同有女儿小璐。'),(182,'A：妻亡，林不在死亡现场。'),(9,'A：葬礼哀痛。'),(23,'A：不要求女儿以复仇继承母亲。'),(83,'A：与玛悼念安雅并保留失落。')],'情感亲近=A：夫妻及亡妻思念||恋爱倾向=A：生前婚恋已成立；妻亡后为哀悼状态||家庭认同=A：配偶、孩子母亲||责任=A：照护遗女、追查死因','新后辈关系不抹去安雅；历史结婚与亡妻现状区分。','13',{'称呼':'A：妻子/安雅。','主观家庭认同':'A：明确配偶。','双方情感承诺':'A：婚姻成立；并非与每位后辈同类承诺。','实际共同生活':'A：生前共同家庭。','社会公开关系':'A：林安夫妻和女儿；魔法身份公开另论。','法律亲属关系':'A：正文明确结婚；未补登记日和证件。','血缘关系':'F：夫妻不等血亲；无证据另建血缘。'})
R(3,48,'旧友／决裂','生日事件后选择结束来往，不继续报复；对方永久改变未知。',[(38,'A：旧友伤害被揭明，李道歉并说还钱；夏选择断交而不继续报复。')],'熟悉度=A：有旧交及借款纠葛||戒备=A：不再延续往来||信任=A：旧信任破裂，未见恢复','李的还款承诺不是已经还清；原谅与恢复友情分开。','14')
R(5,1,'后辈／爱慕／同僚','告白遭明确拒绝后仍表达情意并任秘书合作；不是情侣。',[(50,'A：少年受救；D：本人说自初二暗恋，后来确认同一身份。'),(51,'A：对订婚有失落，离城后回城查案。'),(52,'A：受控中设法促林复出。'),(54,'A：恢复后明确表白，听见拒绝。'),(76,'A：希望支援保护翠雀，选择秘书方案；对方谢谢/对不起不是接受恋情。'),(86,'A：已以侄女掩护任秘书；此为假身份不是血亲。'),(114,'A：继续祝生日与表达情意。')],'熟悉度=A：旧队同伴，知道林翠同一||信任=A：在危机中求助并投入支援||责任=A：表达保护意愿并实际协作||情感亲近=A：暗恋和表白||恋爱倾向=A：单向表白CONFIRMED；双向恋爱未成立','不在演唱会现场；陪买衣、感谢、任秘书均不推翻拒绝；侄女是假履历。','15,17,34',None,True)
